class TransformPipeline:
    def __init__(self, data):
        self.data = data

    def filter_nulls(self):
        return [item for item in self.data if item is not None]

    def normalize_strings(self, data):
        return [item.strip().lower() if isinstance(item, str) else item for item in data]

    def deduplicate(self, data):
        seen = set()
        return [x for x in data if not (x in seen or seen.add(x))]

    def sort_data(self, data):
        return sorted(data)

    def pipe(self, transforms, initial_data=None):
        if initial_data is None:
            initial_data = self.data
        for transform in transforms:
            initial_data = transform(initial_data)
        return initial_data

# Usage example:
# pipeline = TransformPipeline(initial_data)
